def min_spanning_tree(edges: Iterable[Tuple[str, str, int]]) -> List[Tuple[str, str, int]]:
    # Track original index to preserve input order in output
    indexed_roads = []
    for i, (a, b, km) in enumerate(edges):
        if a == b:
            continue
        u, v = sorted((a, b))
        indexed_roads.append((km, u, v, i))

    parent: Dict[str, str] = {}

    def find(code: str) -> str:
        parent.setdefault(code, code)
        while parent[code] != code:
            parent[code] = parent[parent[code]]
            code = parent[code]
        return code

    chosen = []
    # Sort by km, then normalized names (u, v) for tie-breaking
    for km, u, v, idx in sorted(indexed_roads):
        root_u, root_v = find(u), find(v)
        if root_u != root_v:
            parent[root_u] = root_v
            # Store the original tuple (a, b, km) from the input, or normalized
